    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def regions(n, separators):
        bounds = [-1] + separators + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_regions = regions(h, sep_rows)
    col_regions = regions(w, sep_cols)
    out = [row[:] for row in grid]

    # Use the pattern in the first compartment as a tile for every compartment.
    r0, r1 = row_regions[0]
    c0, c1 = col_regions[0]
    tile = [grid[r][c0:c1] for r in range(r0, r1)]
    th, tw = r1 - r0, c1 - c0

    for a, b in row_regions:
        for x, y in col_regions:
            if b - a != th or y - x != tw:
                continue
            for dr in range(th):
                for dc in range(tw):
                    if tile[dr][dc] != 1:
                        out[a + dr][x + dc] = tile[dr][dc]
    return out
